const styles="\n:host{color-scheme:dark;--bg:#090c10;--panel:#10161e;--border:#263141;--muted:#8998ad;--ink:#e1e8f3;--blue:#8cbaff;--deep:#476fa6}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:15px/1.5 system-ui,-apple-system,sans-serif}button{font:inherit;color:inherit;cursor:pointer}button:focus-visible,a:focus-visible{outline:2px solid var(--blue);outline-offset:4px}main{max-width:1100px;padding:36px 28px 64px;margin:auto}.mono,.eyebrow,.switch,small,.metric-label,.legend,.readout,.day-labels{font-family:ui-monospace,SFMono-Regular,Consolas,monospace}header{display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid var(--border);padding-bottom:26px}header strong{font-size:23px;letter-spacing:-1px}header a{color:var(--muted);text-decoration:none;font-size:13px}.notice{display:flex;align-items:center;gap:9px;font-size:12px;color:#b2c9e9;margin:32px 0 54px}.notice:before{content:'';width:6px;height:6px;border-radius:50%;background:var(--blue)}.section-top{display:flex;justify-content:space-between;align-items:center;gap:18px;margin-bottom:26px}.section-top h2{font-size:28px;font-weight:550;letter-spacing:-1px;margin:0}.section-top h2 span{font:12px ui-monospace,monospace;color:var(--muted);margin-right:18px}.section-top p{font-size:13px;color:var(--muted);margin:7px 0 0 39px}.switch{display:flex;gap:4px;background:#111720;border:1px solid var(--border);padding:4px;border-radius:10px;font-size:12px;flex-shrink:0}.switch button{background:none;border:0;border-radius:6px;padding:8px 11px;color:var(--muted)}.switch button[aria-pressed=true]{background:#26374f;color:#d6e7ff}.grid{display:grid;grid-template-columns:minmax(0,1.9fr) minmax(260px,1fr);gap:18px}.card{border:1px solid var(--border);border-radius:18px;background:linear-gradient(145deg,#111923,#10151c);padding:26px;min-width:0}.eyebrow{font-size:11px;letter-spacing:1.8px;color:var(--muted);text-transform:uppercase}.total{font-size:44px;line-height:1.2;letter-spacing:-2px;font-weight:500;margin-top:12px;font-variant-numeric:tabular-nums}.total small{font-size:13px;letter-spacing:0;color:var(--muted);margin-left:8px}.range{font-size:12px;color:var(--muted);margin-top:8px}.stats{display:flex;gap:36px;border-top:1px solid var(--border);margin-top:23px;padding-top:18px}.metric-label{font-size:11px;color:var(--muted)}.metric-value{font-size:19px;margin-top:5px;font-variant-numeric:tabular-nums}.chart-area{position:relative;margin-top:27px}.bars{height:150px;display:flex;gap:5px;align-items:stretch;position:relative;background:repeating-linear-gradient(to top,transparent 0,transparent 49px,#26314180 49px,#26314180 50px)}.bar{position:relative;display:flex;align-items:flex-end;justify-content:center;flex:1;min-width:0;border:0;background:none;padding:0 0 0;transition:opacity .18s}.bar .fill{display:flex;flex-direction:column;justify-content:flex-end;width:100%;max-width:44px;border-radius:4px 4px 0 0;overflow:hidden;min-height:3px;transition:height .35s ease,filter .2s}.bar .c{background:var(--blue)}.bar .x{background:var(--deep)}.bar:hover .fill,.bar[aria-pressed=true] .fill{filter:brightness(1.3)}.bar[aria-pressed=true]:after{content:'';position:absolute;width:4px;height:4px;border-radius:50%;background:#e0ebff;bottom:-10px}.bar.missing .fill{height:4px!important;background:repeating-linear-gradient(135deg,#41516a 0 2px,transparent 2px 4px)}.bar.partial .fill{outline:1px dashed #c2d6f4;outline-offset:-1px}.day-labels{display:flex;justify-content:space-between;color:var(--muted);font-size:10px;margin-top:17px}.readout{display:flex;justify-content:space-between;gap:10px;padding:15px 0 0;margin-top:12px;border-top:1px solid var(--border);font-size:11px;color:var(--muted);min-height:49px}.readout strong{font-weight:400;color:#d7e8ff;text-align:right}.legend{display:flex;flex-wrap:wrap;gap:18px;font-size:11px;color:var(--muted);margin-top:15px}.dot{display:inline-block;width:7px;height:7px;border-radius:2px;background:var(--blue);margin-right:7px}.dot.codex{background:var(--deep)}h2{font-weight:500;font-size:20px;letter-spacing:-.4px;margin:9px 0 0}.sharebar{display:flex;height:15px;gap:4px;margin:30px 0 26px}.sharebar span{background:var(--blue);border-radius:4px;transition:width .35s}.sharebar span+span{background:var(--deep)}.provider{border-bottom:1px solid var(--border);padding:17px 0}.provider-line{display:flex;justify-content:space-between;align-items:center}.provider-name{font-size:14px}.provider-value{font-size:20px;letter-spacing:-.6px;font-variant-numeric:tabular-nums}.share{font:11px ui-monospace,monospace;color:var(--muted);margin:4px 0 0 14px}.footnote{font-size:12px;color:var(--muted);line-height:1.65;margin:26px 0 0}.bottom{margin-top:20px;display:flex;justify-content:space-between;gap:20px;font-size:11px;color:var(--muted)}.sample-tag{display:inline-block;padding:3px 7px;border:1px solid #344863;border-radius:5px;color:#b9cfee;font-size:10px;letter-spacing:1px}.hint{margin-top:48px;color:var(--muted);font-size:13px;max-width:650px}.hint strong{color:#c2cddd;font-weight:450}@media(max-width:760px){.grid{grid-template-columns:1fr}.section-top{align-items:flex-start}.section-top h2{font-size:23px}.section-top h2 span{margin-right:10px}.section-top p{margin-left:0;font-size:12px}.card{padding:22px}.notice{margin-bottom:35px}main{padding:24px 18px}.switch button{padding:7px 8px}.total{font-size:38px}.bars{gap:3px}.bottom{flex-direction:column;gap:4px}.readout{font-size:10px}.sharebar{margin:22px 0 12px}}@media(prefers-reduced-motion:reduce){*{transition:none!important}}\n\n:host{display:block;font:15px/1.5 system-ui;color:var(--ink)}.section-top h2{font-size:24px}.agents{margin-top:18px;padding-top:18px;border-top:1px solid var(--border)}.agents strong{font-size:24px;font-weight:500}.load-status{font-size:12px;color:var(--muted);margin:12px 0}.switch button:disabled{opacity:.5}.dot.output{background:#b1d5e8}@media(max-width:440px){.section-top{flex-direction:column}.stats{gap:18px}.card{padding:18px}}";
const markup="<section aria-labelledby=\"title\"><div class=\"section-top\"><div><h2 id=\"title\">Token &amp; agent activity</h2><p>Daily consumption \u00b7 Seattle time</p></div><div class=\"switch\" aria-label=\"Usage period\"><button data-days=\"7\" aria-pressed=\"true\">7 days</button><button data-days=\"30\" aria-pressed=\"false\">30 days</button></div></div>\n<div class=\"grid\"><article class=\"card\"><div class=\"eyebrow\">Tokens processed <span id=\"period-label\">/ 7 days</span></div><div class=\"total\"><span id=\"total\"></span><small>tokens</small></div><div class=\"range\" id=\"range\"></div><div class=\"stats\"><div><div class=\"metric-label\">TODAY \u00b7 SO FAR</div><div class=\"metric-value\" id=\"today\"></div></div><div><div class=\"metric-label\">REPORTED-DAY AVG</div><div class=\"metric-value\" id=\"average\"></div></div></div>\n<div class=\"load-status\" id=\"load-status\" role=\"status\">Loading usage history\u2026</div><div class=\"switch\" aria-label=\"Metric\"><button data-metric=\"tokens\" aria-pressed=\"true\">Tokens</button><button data-metric=\"agents\" aria-pressed=\"false\">Peak agents</button></div><div class=\"chart-area\"><div class=\"bars\" id=\"bars\" role=\"group\" aria-label=\"Daily token usage. Focus or tap a day for details.\"></div><div class=\"day-labels\"><span id=\"first-date\"></span><span id=\"mid-date\"></span><span>Today</span></div></div><div class=\"readout\" aria-live=\"polite\"><span id=\"detail-date\"></span><strong id=\"detail-value\"></strong></div><div class=\"legend\"><span><i class=\"dot\"></i>Input (uncached)</span><span><i class=\"dot codex\"></i>Cached input</span><span><i class=\"dot output\"></i>Output</span></div></article>\n<article class=\"card\"><div class=\"eyebrow\">Token breakdown</div><h2>Where the tokens go.</h2><div class=\"agents\"><div class=\"metric-label\">CONCURRENT AGENTS NOW</div><strong id=\"agents-now\">\u2014</strong><div id=\"agent-state\" class=\"range\">Checking tracker\u2026</div></div><div class=\"sharebar\" aria-hidden=\"true\"><span id=\"claude-share\"></span><span id=\"codex-share\"></span><span id=\"output-share\" style=\"background:#b1d5e8\"></span></div><div class=\"provider\"><div class=\"provider-line\"><span class=\"provider-name\"><i class=\"dot\"></i>Input (uncached)</span><span class=\"provider-value\" id=\"claude-total\"></span></div><div class=\"share\" id=\"claude-percent\"></div></div><div class=\"provider\"><div class=\"provider-line\"><span class=\"provider-name\"><i class=\"dot codex\"></i>Cached input</span><span class=\"provider-value\" id=\"codex-total\"></span></div><div class=\"share\" id=\"codex-percent\"></div></div><div class=\"provider\"><div class=\"provider-line\"><span><i class=\"dot output\"></i>Output</span><span class=\"provider-value\" id=\"output-total\">\u2014</span></div><div class=\"share\" id=\"output-percent\"></div></div><p class=\"footnote\">Cached tokens are part of input, not extra tokens. Counts describe usage, not a bill.</p><p class=\"footnote\" id=\"coverage\"></p></article></div>\n<div class=\"bottom mono\"><span>Hover, focus, or tap a day to explore.</span><span>Daily agent peaks are observed counts, not unique agents.</span></div></section>";
const short=n=>new Intl.NumberFormat('en-US',{notation:'compact',maximumFractionDigits:2}).format(n);
const label=date=>new Date(date+'T12:00:00Z').toLocaleDateString('en-US',{month:'short',day:'numeric',timeZone:'UTC'});
class UsagePanel extends HTMLElement{
 connectedCallback(){if(this.shadowRoot)return;this.root=this.attachShadow({mode:'open'});this.root.innerHTML='<style>'+styles+'</style>'+markup;this.days=7;this.metric='tokens';this.history=null;this.live=null;this.busy=false;this.lastHistory=0;
 this.root.querySelectorAll('[data-days]').forEach(b=>b.onclick=()=>{this.days=Number(b.dataset.days);this.render()});
 this.root.querySelectorAll('[data-metric]').forEach(b=>b.onclick=()=>{this.metric=b.dataset.metric;this.render()});
 this.visibility=()=>{clearTimeout(this.timer);if(!document.hidden)this.poll()};document.addEventListener('visibilitychange',this.visibility);this.render();this.poll();}
 disconnectedCallback(){clearTimeout(this.timer);document.removeEventListener('visibilitychange',this.visibility);}
 set(id,text){this.root.getElementById(id).textContent=text;}
 async poll(){clearTimeout(this.timer);if(this.busy||document.hidden||!this.isConnected)return;this.busy=true;let redraw=false;
 const read=async url=>{const r=await fetch(url,{signal:AbortSignal.timeout(8000)});if(!r.ok)throw Error();return r.json()};
 try{const jobs=[read('/api/workstation/status').then(d=>{this.live=d},()=>{this.live=null})];if(Date.now()-this.lastHistory>30000)jobs.push(read('/api/workstation/history').then(d=>{if(!Array.isArray(d.days)||d.days.length!==30)throw Error();this.history=d;redraw=true;this.lastHistory=Date.now();this.failed=false},()=>{this.failed=true;redraw=true}));await Promise.all(jobs);}catch{this.failed=true;}finally{this.busy=false;if(redraw||!this.history)this.render();else this.renderAgents();if(this.isConnected&&!document.hidden)this.timer=setTimeout(()=>this.poll(),5000);}}
 renderAgents(){ const active=this.live?.tracker==='connected'?this.live.agents:null;this.set('agents-now',active?.active==null?'—':String(active.active)+(active.coverage==='partial'?'+':''));this.set('agent-state',!this.live?'Status unavailable':this.live.tracker!=='connected'?'Offline · tracker disconnected':active?.active==null?'Connected · count unavailable':active.active>0?'Online · agents active':'Offline · no agents reported');}

 render(){const r=this.root;for(const b of r.querySelectorAll('[data-days]'))b.setAttribute('aria-pressed',String(Number(b.dataset.days)===this.days));for(const b of r.querySelectorAll('[data-metric]'))b.setAttribute('aria-pressed',String(b.dataset.metric===this.metric));
 const rows=this.history?.days.slice(-this.days)||[],known=rows.filter(d=>d.tokens?.total!=null),sum=known.reduce((s,d)=>s+d.tokens.total,0),incomplete=rows.length!==known.length||known.some(d=>d.tokens.coverage==='partial');
 const val=n=>known.length?short(n)+(incomplete?'+':''):'—';this.set('total',val(sum));this.set('period-label','/ '+this.days+' days');this.set('range',rows.length?label(rows[0].date)+' – '+label(rows.at(-1).date):'Waiting for recorded history');const today=rows.at(-1)?.tokens;this.set('today',today?.total==null?'—':short(today.total)+(today.coverage==='partial'?'+':''));this.set('average',val(sum/(known.length||1)));
 this.set('load-status',this.failed?(this.history?'Update unavailable · showing last received history':'Usage history is temporarily unavailable.'):!this.history?'Loading usage history…':this.metric==='agents'?'Highest concurrent count received each day. Tracking starts with this release.':'Daily total includes input and output; cached input is included once.');
 this.renderAgents();
 const totals=[known.reduce((s,d)=>s+d.tokens.input-d.tokens.cachedInput,0),known.reduce((s,d)=>s+d.tokens.cachedInput,0),known.reduce((s,d)=>s+d.tokens.output,0)];['claude','codex','output'].forEach((key,i)=>{this.set(key+'-total',val(totals[i]));this.set(key+'-percent',known.length?(sum?Math.round(totals[i]/sum*100):0)+'% of reported tokens':'No data reported');r.getElementById(key+'-share').style.width=(sum?totals[i]/sum*100:0)+'%'});
 this.set('coverage',known.length+' of '+this.days+' days have token data. “+” marks a lower bound. Average uses reported days, including today so far.');
 const bars=r.getElementById('bars');bars.replaceChildren();const count=d=>this.metric==='tokens'?d.tokens?.total:d.agentsPeak?.active,max=Math.max(1,...rows.map(d=>count(d)||0));
 const select=(d,b)=>{for(const x of bars.children)x.setAttribute('aria-pressed',String(x===b));const n=count(d),partial=(this.metric==='tokens'?d.tokens:d.agentsPeak)?.coverage==='partial';this.set('detail-date',label(d.date)+(partial?' · partial':''));this.set('detail-value',n==null?'No data reported':n.toLocaleString()+(partial?'+':'')+(this.metric==='tokens'?' tokens':' concurrent · observed peak'));};
 for(const d of rows){const n=count(d),partial=(this.metric==='tokens'?d.tokens:d.agentsPeak)?.coverage==='partial',b=document.createElement('button');b.className='bar'+(n==null?' missing':'')+(partial?' partial':'');b.setAttribute('aria-label',label(d.date)+': '+(n==null?'unavailable':n.toLocaleString()+(partial?' or more':'')+(this.metric==='tokens'?' tokens':' observed peak agents')));const fill=document.createElement('span');fill.className='fill';fill.style.height=(n==null?0:n/max*100)+'%';if(n!=null){const parts=this.metric==='tokens'?[d.tokens.input-d.tokens.cachedInput,d.tokens.cachedInput,d.tokens.output]:[n];parts.forEach((v,i)=>{const s=document.createElement('span');s.style.height=(n?v/n*100:100)+'%';s.style.background=['#8cbaff','#476fa6','#b1d5e8'][i];fill.append(s)})}b.append(fill);for(const e of ['mouseenter','focus','click'])b.addEventListener(e,()=>select(d,b));bars.append(b)}
 if(rows.length){this.set('first-date',label(rows[0].date));this.set('mid-date',label(rows[Math.floor(rows.length/2)].date));select(rows.at(-1),bars.lastChild)}else{this.set('detail-date','');this.set('detail-value','No data reported')}
 r.querySelector('.legend').hidden=this.metric==='agents';
 }
}
customElements.define('usage-panel',UsagePanel);
